from pathlib import Path
import argparse,json,html
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();r=a.root;o=r/'resultados'
verification=json.loads((r/'verificacion_final.json').read_text());assert verification['status']=='verified'
s=pd.read_csv(o/'resumen.csv');c=pd.read_csv(o/'contrastes.csv');per=pd.read_csv(o/'por_semilla.csv');paired=json.loads((o/'pareadas.json').read_text())
def table(df):
 labels={'arm':'Brazo','features':'Variables','seeds':'Modelos','auc_validation':'AUC agosto','validation_contacts':'Contactos agosto','contacts_policy':'Contactos octubre','gain_policy':'Ganancia con política propia','hits_policy':'BAJA+2 detectadas','contacts_common_A':'Contactos comunes','gain_common_A':'Ganancia a igual presupuesto','gain_11000':'Ganancia a 11.000','representation':'Representación','comparison':'Comparación','metric':'Métrica','delta':'Diferencia','mean':'Media','median':'Mediana','std':'Desvío','min':'Mínimo','max':'Máximo','contacts':'Contactos','retained':'Permanecen','entered':'Entran','exited':'Salen','BAJA2_entered':'BAJA+2 que entran','BAJA2_exited':'BAJA+2 que salen','delta_gain':'Diferencia de ganancia'}
 display=df.copy()
 if 'metric' in display:display['metric']=display.metric.replace(labels)
 return display.rename(columns=labels).to_html(index=False,float_format=lambda v:f'{v:,.6f}')
index=s.set_index('arm');delta=lambda l,rr,col:int(index.loc[l,col]-index.loc[rr,col]);money=lambda n:f'${n:,.0f}'.replace(',','.')
lines=[]
for l,rr,label in [('B','A','Variables y reoptimización con una semilla'),('C','A','Ensemble del baseline'),('D','B','Ensemble de la representación enriquecida'),('D','C','Variables y reoptimización con ensemble'),('D','A','Paquete completo frente al baseline de una semilla')]:
 lines.append(f'{label}: diferencia {money(delta(l,rr,"gain_policy"))} con políticas propias elegidas en agosto; {money(delta(l,rr,"gain_common_A"))} al presupuesto común de A.')
fig,axes=plt.subplots(1,2,figsize=(12,4.7),layout='constrained')
for ax,col,title in zip(axes,['gain_policy','gain_common_A'],['Políticas propias fijadas en agosto','Mismo presupuesto: política de A']):
 vals=s[col]/1e6;ax.bar(s.arm,vals,color=['#536878','#2c7a7b','#5677a0','#259b91']);ax.axhline(0,color='#333');ax.set_title(title);ax.set_ylabel('Ganancia octubre 2019 · millones de pesos');ax.set_ylim(min(0,vals.min()*1.15),max(1,vals.max()*1.18))
 for i,v in enumerate(vals):ax.text(i,v,f'{v:.2f}',ha='center',va='bottom')
fig.savefig(r/'ganancias.png',dpi=160);plt.close(fig)
wide=per.pivot(index='seed',columns='representation',values='gain_common_A');dif=wide.enriquecido-wide.baseline
fig,ax=plt.subplots(figsize=(11,4),layout='constrained');ax.bar(range(len(dif)),dif/1e6,color=['#2c7a7b' if v>=0 else '#bb5d50' for v in dif]);ax.axhline(0,color='black');ax.set_xticks(range(len(dif)),dif.index,rotation=60);ax.set_ylabel('Enriquecido − baseline · millones');ax.set_title('Diferencias por semilla, mismo presupuesto de contactos');fig.savefig(r/'semillas.png',dpi=160);plt.close(fig)
body='''<!doctype html><html lang="es"><meta charset="utf-8"><title>Ale + C3 en octubre 2019</title><style>body{font:17px/1.55 system-ui;max-width:1250px;margin:30px auto;padding:24px;color:#173549}h2{margin-top:38px}table{border-collapse:collapse;font-size:14px;width:100%;display:block;overflow:auto}th,td{padding:8px;border:1px solid #cad7df}th{background:#eef4f6}img{max-width:100%}.note{padding:20px;background:#fff0d9}a{color:#176b8c}</style><h1>Baseline de Ale + variables de C3 en 2019</h1><p>Corrida A/B/C/D: resultados locales sobre octubre de 2019 completo. No son resultados públicos o privados de Kaggle ni la ganancia de C3 en 2021.</p><div class="note">Octubre ya se había observado en experimentos anteriores. Este ensayo es exploratorio y no constituye una confirmación temporal independiente. Veinte semillas son veinte entrenamientos sobre los mismos clientes, no veinte meses.</div><h2>Pregunta e hipótesis</h2><p>¿Mejora la ganancia al agregar 43 variables intrames de C3 al B2 de Ale? ¿Mejora al promediar 20 modelos? Se estudian por separado y juntas, con el mismo calendario, target y fórmula económica.</p><h2>Qué se comparó</h2><ul><li>A: B2 (722 variables), una semilla fijada previamente.</li><li>B: B2 + 43 variables de C3 (765), la misma semilla.</li><li>C: ensemble de 20 semillas del baseline, incluyendo A.</li><li>D: ensemble de las mismas 20 semillas de la representación enriquecida, incluyendo B.</li></ul><p>Las 43 variables son 27 ratios monto/operaciones y 16 sumas Visa+Master. Fórmulas verificadas contra C3. Las sumas requieren ambas marcas finitas. No se transfirió toda la historia ni toda la receta C3. Entrenamiento: marzo–junio 2019 completo; validación: agosto; evaluación: octubre. Target de AUC: BAJA+1 y BAJA+2. Ganancia: sólo BAJA+2.</p><p>Se ejecutaron 20 trials por representación y luego 20 semillas con parámetros y árboles fijos de su trial elegido por AUC. A/B cambian representación y parámetros: la comparación es entre recetas reoptimizadas. C/A y D/B comparan ensemble y una semilla previamente fijada. No se seleccionó una semilla ganadora.</p><h2>Resultados principales</h2>'''+table(s)+'''<p>gain_policy: ganancia con la política propia del brazo. gain_common_A: ganancia con la cantidad de contactos elegida por A. gain_11000: referencia secundaria a 11.000. Todas las ganancias en pesos.</p><img src="ganancias.png" alt="Ganancias con políticas propias y presupuesto común"><h2>Lectura de los contrastes</h2><ul>'''+''.join('<li>'+html.escape(x)+'</li>' for x in lines)+'''</ul><p>Un delta positivo es mejora observada en este mes, no prueba estadística ni promesa de ganancia futura. Si el signo cambia al igualar contactos, cambia la interpretación: la política y el ranking no aportan lo mismo.</p>'''+table(c)+'''<h2>Estabilidad por semilla</h2>'''+table(pd.DataFrame([paired]))+'''<img src="semillas.png" alt="Diferencias pareadas"><p>El promedio de ganancias de las semillas no es la ganancia del ensemble. El ensemble promedia scores y recién después ordena y selecciona clientes.</p><h2>Política de contactos</h2><p>Cada brazo elige en agosto el máximo de ganancia, incluyendo cero contactos, y transfiere su fracción a octubre con redondeo hacia abajo. Empates de score: identificador ascendente. Los cortes fueron congelados antes de abrir octubre en esta corrida. No se impuso el rango 3.600–5.700 ni se buscó un corte óptimo mirando octubre. Los 11.000 contactos siguen siendo una referencia válida.</p><h2>Referencia B2 y controles</h2><p>Se reprodujeron los scores históricos de B2 en agosto y su curva completa de octubre. Los $282.645.000 históricos a 5.042 contactos se mantienen como antecedente: la nueva política usa floor, mientras la anterior redondeaba al entero más cercano, por lo que puede variar un contacto sin variar el modelo.</p><p>Se verificaron 40 modelos por hash y número de árboles, semillas, media exacta de scores, políticas de agosto y ganancias recalculadas desde las predicciones. <a href="verificacion_final.json">Controles finales</a>.</p><h2>Limitaciones y siguientes pasos</h2><ul><li>Un único octubre previamente observado; validar temporalmente fuera de lo ya utilizado antes de promover.</li><li>Variables y reoptimización van juntas; una ablación con parámetros comunes permitiría atribución más específica.</li><li>La familia mezcla tickets y sumas: no identifica qué variable causó un cambio.</li><li>La escala de Visa_msaldototal y la cobertura de ambas marcas requieren cautela interpretativa; no se aplicaron correcciones oportunistas.</li><li>Las políticas se eligieron en la misma validación usada para optimizar: posible sobreajuste de agosto.</li></ul><h2>Reproducción y entregables</h2><p><a href="REPRODUCIR.txt">Reproducir</a> · <a href="PROTOCOLO.md">Protocolo previo</a> · <a href="variables_propuestas.csv">43 variables</a> · <a href="resultados/resumen.csv">Resultados CSV</a> · <a href="guion_video.txt">Guion para el video</a></p></html>'''
body=body.replace('<h2>Referencia B2 y controles</h2>','<h2>Referencia B2 y controles</h2><p>Igualdad exacta del nuevo A con los scores históricos de B2: agosto '+str(verification['new_A_equals_historical_B2_validation'])+'; octubre '+str(verification['new_A_equals_historical_B2_test'])+'.</p>')
hp=[]
for rep in ['baseline','enriquecido']:
 chosen=json.loads((o/rep/'BO_COMPLETE.json').read_text());hp.append({'representation':rep,'trees':chosen['trees'],'best_trial':chosen['best_trial'],**chosen['best_params']})
body=body.replace('<h2>Resultados principales</h2>','<h2>Hiperparámetros elegidos en agosto</h2>'+table(pd.DataFrame(hp))+'<p>Comunes: bagging_freq=1, max_bin=255, deterministic=true, force_col_wise=true; sin muestreo de filas fuera del bagging interno del modelo. Cada representación mantiene sus parámetros y árboles en las 20 semillas.</p><h2>Resultados principales</h2>')
body=body.replace('<h2>Política de contactos</h2>','<h2>Qué cambió en los clientes seleccionados</h2>'+table(pd.read_csv(o/'seleccion.csv'))+'<p>A igual número de contactos, cada acierto neto adicional suma $1.100.000. Se muestran entradas y salidas del conjunto seleccionado, sin identificar clientes. Es una explicación contable del cambio observado, no atribución causal a variables individuales.</p><h2>Política de contactos</h2>')
stability=per.groupby('representation').gain_common_A.agg(['mean','median','std','min','max']).reset_index()
body=body.replace('<h2>Estabilidad por semilla</h2>','<h2>Estabilidad por semilla</h2>'+table(stability)+'<p>Resumen descriptivo de las 20 ganancias individuales al presupuesto común. Máximo y mínimo no se usan para seleccionar semillas ni reemplazar A/B.</p>')
body=body.replace('<h2>Reproducción y entregables</h2>','<h2>Correcciones de ejecución</h2><p>Antes del primer trial completado se corrigió la declaración de categorías en validación. Durante el entrenamiento se detectó que la lista inicial tenía 19 semillas pese al diseño de 20: se agregó 1809, siguiendo la secuencia numérica, sin reemplazar semillas según su desempeño. Se preservaron los 19 modelos completos del baseline. Esta corrección ocurrió antes del congelamiento y de abrir octubre en esta corrida. Las firmas anteriores y el incidente se conservaron; la verificación final exige 20 semillas únicas por representación y 40 modelos. Ver IMPLEMENTACION.txt y el historial Git.</p><h2>Reproducción y entregables</h2>')
conclusion=(f"B obtiene la mayor ganancia con su política fijada en agosto: {money(index.loc['B','gain_policy'])}, "
 f"{money(delta('B','A','gain_policy'))} más que A. A igual presupuesto de A, su diferencia es {money(delta('B','A','gain_common_A'))}. "
 f"Sin embargo, la versión enriquecida gana sólo {paired['wins']} de 20 comparaciones pareadas a ese presupuesto "
 f"y su diferencia media es {money(paired['mean_delta'])}. El resultado favorable de la semilla principal no es una mejora consistente. "
 "C y D no superan a sus modelos individuales con sus políticas propias. C mejora ligeramente el ranking al igualar contactos, pero pierde ganancia con su corte elegido en agosto. "
 "No se justifica adoptar automáticamente las variables o los ensembles por esta corrida. Falta aislar variables de reoptimización y validar temporalmente fuera de los períodos observados.")
body=body.replace('<h2>Pregunta e hipótesis</h2>','<h2>Conclusión de esta corrida</h2><p>'+conclusion+'</p><h2>Pregunta e hipótesis</h2>')
manifest=pd.read_csv(r/'variables_propuestas.csv');new_names=set(manifest.variable);usage=[]
for path in (o/'enriquecido').glob('*/importance.csv'):
 im=pd.read_csv(path);new=im[im.feature.isin(new_names)];usage.append({'semilla':int(path.parent.name),'variables_nuevas_usadas':int((new['split']>0).sum()),'porcentaje_importancia_interna':float(100*new.gain.sum()/im.gain.sum())})
pd.DataFrame(usage).to_csv(r/'uso_variables_nuevas.csv',index=False)
body=body.replace('<h2>Limitaciones y siguientes pasos</h2>','<h2>Uso de las variables incorporadas</h2>'+table(pd.DataFrame(usage))+'<p>Importancia interna de LightGBM: no es porcentaje de ganancia económica ni efecto causal. Usar una variable en árboles no demuestra que mejore la selección de contactos.</p><h2>Limitaciones y siguientes pasos</h2>')
(r/'conclusiones.txt').write_text(conclusion+'\n\n'+'\n'.join(lines))
(r/'informe.html').write_text(body)
script=['VIDEO — BASELINE ALE + SUBCONJUNTO C3 EN 2019','Hipótesis: transferir ratios monto/operaciones y sumas Visa+Master y promediar semillas puede mejorar el ranking o estabilizarlo.','Diseño: cuatro brazos; dos representaciones con 20 trials cada una y 20 semillas pareadas. Marzo–junio para entrenamiento, agosto para selección y política, octubre para evaluación. A y B son semillas predefinidas dentro de C y D.','Resultados:']
for row in s.itertuples():script.append(f'{row.arm}: {money(row.gain_policy)} a {row.contacts_policy} contactos; {money(row.gain_common_A)} al presupuesto de A; {money(row.gain_11000)} a 11.000.')
script+=lines+[conclusion, 'Limitaciones: octubre ya observado, un solo mes y selección de parámetros y contactos en el mismo agosto. Las semillas no son muestras temporales independientes. Variables y reoptimización cambian juntas.','Conclusión: interpretar los contrastes por separado, publicar también los negativos y validar en otro período antes de adoptar. Próximo paso: ablaciones de las familias con parámetros comunes si los resultados justifican seguir.']
(r/'guion_video.txt').write_text('\n\n'.join(script));print(s.to_string(index=False))
